{"explanation":"The law of cosines is the Pythagorean theorem with a correction: c² = a² + b² − 2ab cos θ, where θ is the angle between sides a and b. Dropping a perpendicular gives c² = (a − b cos θ)² + (b sin θ)², which expands to that formula. At 90° the correction vanishes; for an acute angle it subtracts from a² + b², and for an obtuse angle it adds.","manimCode":"let theta = Math.PI / 3;
const a = 3.4;
const b = 2.6;
const A = [-3, -1.6, 0];
const B = [A[0] + a, A[1], 0];
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

const title = new Text({ text: 'Pythagoras + an angle correction', fontSize: 32, color: WHITE });
title.moveTo([0, 3.15, 0]);
const divider = new Line({ start: [0.85, -2.65, 0], end: [0.85, 2.5, 0], color: GRAY });
divider.setOpacity(0.35);

const triangle = new Polygon({ vertices: [A, B, [-1.7, 0.65, 0]], color: BLUE });
triangle.setFill(BLUE, 0.12);
const altitude = new DashedLine({ start: [-1.7, -1.6, 0], end: [-1.7, 0.65, 0], color: GRAY });
const projection = new Line({ start: A, end: [-1.7, -1.6, 0], color: TEAL });
projection.setStrokeWidth(6);
const horizontal = new Line({ start: [-1.7, -1.6, 0], end: B, color: ORANGE });
horizontal.setStrokeWidth(4);
const corner = new Polygon({ vertices: [[0, 0, 0], [0.1, 0, 0], [0.1, 0.1, 0]], color: GRAY });
corner.setFillOpacity(0);
const handle = new Dot({ point: [-1.7, 0.65, 0], radius: 0.14, color: YELLOW });
const originDot = new Dot({ point: A, radius: 0.05, color: WHITE });
const endDot = new Dot({ point: B, radius: 0.05, color: WHITE });

const aLabel = new Text({ text: 'a', fontSize: 25, color: BLUE });
aLabel.moveTo([-1.3, -2.05, 0]);
const bLabel = new Text({ text: 'b', fontSize: 25, color: BLUE });
const cLabel = new Text({ text: 'c', fontSize: 25, color: YELLOW });
const angleLabel = new Text({ text: 'θ', fontSize: 24, color: TEAL });
const projectionLabel = new Text({ text: 'b cos θ', fontSize: 20, color: TEAL });
const heightLabel = new Text({ text: 'b sin θ', fontSize: 20, color: GRAY });

const formula = new MathTex({ latex: 'c^2 = a^2 + b^2 - 2ab\\cos\\theta' });
await formula.waitForRender();
formula.scale(0.65);
formula.moveTo([3.4, 2.25, 0]);
const decomposition = new MathTex({ latex: 'c^2=(a-b\\cos\\theta)^2+(b\\sin\\theta)^2' });
await decomposition.waitForRender();
decomposition.scale(0.48);
decomposition.moveTo([3.4, 1.55, 0]);

const angleReadout = new Text({ text: '', fontSize: 24, color: WHITE });
angleReadout.moveTo([3.4, 0.8, 0]);
const baselineReadout = new Text({ text: '', fontSize: 23, color: BLUE });
baselineReadout.moveTo([3.4, 0.2, 0]);
const correctionReadout = new Text({ text: '', fontSize: 23, color: ORANGE });
correctionReadout.moveTo([3.4, -0.4, 0]);
const resultReadout = new Text({ text: '', fontSize: 25, color: YELLOW });
resultReadout.moveTo([3.4, -1.05, 0]);
const interpretation = new Text({ text: '', fontSize: 23, color: WHITE });
interpretation.moveTo([3.4, -1.85, 0]);
const rightAngleButton = new Text({ text: 'Click: set angle to 90°', fontSize: 22, color: TEAL });
rightAngleButton.moveTo([-2.4, -2.8, 0]);
const hint = new Text({ text: 'Drag the yellow vertex around the blue side’s fixed endpoint', fontSize: 21, color: GRAY });
hint.moveTo([0, -3.4, 0]);

const angleSegments = [];
for (let i = 0; i < 18; i++) {
  const segment = new Line({ start: A, end: [A[0] + 0.45, A[1], 0], color: TEAL });
  angleSegments.push(segment);
}
scene.add(title, divider, triangle, altitude, projection, horizontal, corner, ...angleSegments, originDot, endDot, aLabel, bLabel, cLabel, angleLabel, projectionLabel, heightLabel, handle, formula, decomposition, angleReadout, baselineReadout, correctionReadout, resultReadout, interpretation, rightAngleButton, hint);

function update() {
  const px = b * Math.cos(theta);
  const py = b * Math.sin(theta);
  const C = [A[0] + px, A[1] + py, 0];
  const D = [C[0], A[1], 0];
  const correction = -2 * a * b * Math.cos(theta);
  const baseSquared = a * a + b * b;
  const cSquared = baseSquared + correction;
  triangle.setVertices([A, B, C]);
  handle.moveTo(C);
  altitude.setStart(D);
  altitude.setEnd(C);
  projection.setStart(A);
  projection.setEnd(D);
  horizontal.setStart(D);
  horizontal.setEnd(B);
  corner.setVertices([[D[0], D[1] + 0.16, 0], [D[0] + 0.16, D[1] + 0.16, 0], [D[0] + 0.16, D[1], 0]]);
  bLabel.moveTo([(A[0] + C[0]) / 2 - 0.24, (A[1] + C[1]) / 2 + 0.12, 0]);
  cLabel.moveTo([(B[0] + C[0]) / 2 + 0.24, (B[1] + C[1]) / 2 + 0.1, 0]);
  projectionLabel.moveTo([(A[0] + D[0]) / 2, A[1] - 0.7, 0]);
  projectionLabel.setOpacity(Math.abs(px) < 0.15 ? 0 : 1);
  heightLabel.moveTo([D[0] - 0.65, (D[1] + C[1]) / 2, 0]);
  heightLabel.setOpacity(Math.abs(px) < 0.55 ? 0 : 1);
  angleLabel.moveTo([A[0] + 0.75 * Math.cos(theta / 2), A[1] + 0.75 * Math.sin(theta / 2), 0]);
  for (let i = 0; i < angleSegments.length; i++) {
    const t1 = theta * i / angleSegments.length;
    const t2 = theta * (i + 1) / angleSegments.length;
    angleSegments[i].setStart([A[0] + 0.45 * Math.cos(t1), A[1] + 0.45 * Math.sin(t1), 0]);
    angleSegments[i].setEnd([A[0] + 0.45 * Math.cos(t2), A[1] + 0.45 * Math.sin(t2), 0]);
  }
  angleReadout.setText('θ = ' + (theta * 180 / Math.PI).toFixed(1) + '°');
  baselineReadout.setText('Pythagoras: a² + b² = ' + baseSquared.toFixed(2));
  correctionReadout.setText('Correction: ' + (correction >= -0.00001 ? '+' : '−') + ' ' + Math.abs(correction).toFixed(2));
  resultReadout.setText('c² = ' + cSquared.toFixed(2) + '    c = ' + Math.sqrt(cSquared).toFixed(2));
  interpretation.setText(Math.abs(correction) < 0.001 ? '90°: exactly Pythagoras' : correction < 0 ? 'Acute angle: subtract' : 'Obtuse angle: add');
}
update();

makeDraggable(handle, scene, {
  onDrag: (mob, pos) => {
    theta = clamp(Math.atan2(pos[1] - A[1], pos[0] - A[0]), 25 * Math.PI / 180, 145 * Math.PI / 180);
    update();
  }
});
makeClickable(rightAngleButton, scene, {
  onClick: () => { theta = Math.PI / 2; update(); }
});
await scene.wait(999999);"}

